export const c11EngW3HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & EXAM BLUEPRINT CARD -->\n  <div style=\"background: rgba(17, 153, 142, 0.06); border: 1.5px solid #11998E; border-radius: 12px; padding: 18px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h2 class=\"text-center\" style=\"color: #11998E; font-weight: bold; margin: 0 0 6px 0; font-size: 20px;\">✉️ Formal &amp; Business Letter Writing &mdash; Master Exam Blueprint</h2>\n    <p class=\"text-center\" style=\"color: #38EF7D; margin: 0 0 16px 0; font-size: 14.5px;\">Long Writing Skills Hub &bull; Section B &bull; 6 Marks Guaranteed Board Strategy</p>\n\n    <div style=\"display: flex; flex-direction: column; gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #11998E; border-radius: 6px;\">\n        <b style=\"color: #11998E; font-size: 16px; display: block; margin-bottom: 4px;\">1. Official Board Marking Scheme (6 Marks Total):</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          &bull; <b>Format (1 Mark):</b> Full modern block format (Sender's Address, Date, Receiver's Address, Subject, Salutation, Body, Complimentary Close, Sender's Signature &amp; Full Name in capital letters with designation).<br/>\n          &bull; <b>Content (3 Marks):</b> Comprehensive coverage of all bulleted prompts, logical progression, factual coherence, well-reasoned causes, and realistic remedies.<br/>\n          &bull; <b>Expression &amp; Accuracy (2 Marks):</b> Grammatical correctness, mature vocabulary, formal register, appropriate transitional connectors, and strict adherence to the 120&ndash;150 word limit.\n        </span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #11998E; border-radius: 6px;\">\n        <b style=\"color: #11998E; font-size: 16px; display: block; margin-bottom: 4px;\">2. Mandatory Modern Block Format Rule:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          In modern CBSE and JKBOSE examination evaluation, <b>ALL ELEMENTS ARE STRICTLY LEFT-ALIGNED</b> with zero paragraph indentations. <b>DO NOT PUT COMMAS OR FULL STOPS AT THE END OF LINES</b> in the addresses, date, or salutation.\n        </span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 14px 16px; border-left: 4px solid #11998E; border-radius: 6px;\">\n        <b style=\"color: #11998E; font-size: 16px; display: block; margin-bottom: 4px;\">3. The Golden Editorial Rule:</b>\n        <span style=\"color: #FFFFFF; font-size: 15px; line-height: 1.6;\">\n          <b>NEVER ASK THE EDITOR TO SOLVE YOUR CIVIC PROBLEM!</b> The Editor is a journalist, not an executive municipal official. You request the Editor to <i>publish your views</i> in their esteemed columns to awaken public conscience and mobilize the relevant authorities (e.g., Municipal Commissioner, Police, PWD).\n        </span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: ARCHITECTURE OF FORMAL LETTERS -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 30px;\">1. Anatomy &amp; Structural Architecture of a Formal Letter</h2>\n  <p>A formal letter is an official instrument of communication between individuals, institutions, commercial enterprises, or government authorities. Unlike informal correspondence, it demands absolute objectivity, clarity of purpose, emotional neutrality, and courteous professional decorum.</p>\n\n  <div style=\"display: flex; flex-direction: column; gap: 14px; margin: 18px 0;\">\n    <div style=\"background: rgba(17, 153, 142, 0.08); border-left: 4px solid #11998E; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #11998E; font-size: 16px;\">(i) Sender&rsquo;s Address (Top Left):</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Written in 2 to 3 lines. Gives the house number, street name, locality, and city. Never write the sender&rsquo;s name here. If no address is specified in the question, use an examination placeholder such as <i>&ldquo;Examination Hall, ABC City&rdquo;</i>.</p>\n    </div>\n\n    <div style=\"background: rgba(17, 153, 142, 0.08); border-left: 4px solid #11998E; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #11998E; font-size: 16px;\">(ii) Date (One Line Space Below Sender&rsquo;s Address):</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Always write the date in formal alphanumeric format: <i>&ldquo;18th November 2026&rdquo;</i> or <i>&ldquo;November 18, 2026&rdquo;</i>. Strictly avoid numerical slashes like <i>&ldquo;18/11/2026&rdquo;</i> or abbreviations like <i>&ldquo;18-11-26&rdquo;</i> as these attract format deductions.</p>\n    </div>\n\n    <div style=\"background: rgba(17, 153, 142, 0.08); border-left: 4px solid #11998E; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #11998E; font-size: 16px;\">(iii) Receiver&rsquo;s Designation &amp; Official Address:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Must start with the recipient&rsquo;s official title (e.g., <i>&ldquo;The Editor&rdquo;</i>, <i>&ldquo;The Municipal Commissioner&rdquo;</i>, <i>&ldquo;The Sales Manager&rdquo;</i>, <i>&ldquo;The Principal&rdquo;</i>), followed by the name of the organisation/newspaper/firm, street, and city.</p>\n    </div>\n\n    <div style=\"background: rgba(17, 153, 142, 0.08); border-left: 4px solid #11998E; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #11998E; font-size: 16px;\">(iv) Subject Line:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">A concise summary of the letter&rsquo;s purpose in 4 to 8 words. It should be crisp, highlighted, or underlined, e.g., <i>&ldquo;Subject: Urgent need to curb reckless driving in Rajouri Garden&rdquo;</i>.</p>\n    </div>\n\n    <div style=\"background: rgba(17, 153, 142, 0.08); border-left: 4px solid #11998E; padding: 12px 16px; border-radius: 4px;\">\n      <b style=\"color: #11998E; font-size: 16px;\">(v) Salutation &amp; Complimentary Close:</b>\n      <p style=\"margin: 6px 0 0 0; color: #FFFFFF;\">Standard salutation: <i>&ldquo;Sir/Madam&rdquo;</i> or <i>&ldquo;Dear Sir/Madam&rdquo;</i> (never write <i>&ldquo;Respected Sir&rdquo;</i> in modern board practice; &lsquo;Sir&rsquo; itself embodies complete formal respect). Complimentary close: <i>&ldquo;Yours faithfully&rdquo;</i> (standard for unknown recipients/editors/firms) or <i>&ldquo;Yours sincerely&rdquo;</i> (when addressed to named officials). Never put an apostrophe in <i>&ldquo;Yours&rdquo;</i> (writing <i>&ldquo;Your's&rdquo;</i> is a severe grammar error).</p>\n    </div>\n  </div>\n\n  <!-- THE 3-TIER BODY FORMULA CARD -->\n  <div style=\"background: #0B1E1C; border: 2px dashed #11998E; border-radius: 10px; padding: 18px; margin: 24px 0; box-shadow: 0 4px 18px rgba(0,0,0,0.4);\">\n    <div style=\"text-align: center; color: #11998E; font-size: 13px; font-weight: bold; letter-spacing: 1.5px; margin-bottom: 8px;\">[THE UNIVERSAL 3-PARAGRAPH BODY BLUEPRINT]</div>\n    <div style=\"display: flex; flex-direction: column; gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.3); padding: 12px 14px; border-left: 4px solid #38EF7D; border-radius: 4px;\">\n        <b style=\"color: #38EF7D; font-size: 15.5px;\">Paragraph 1 &mdash; Introductory Hook &amp; Purpose of Writing:</b>\n        <p style=\"margin: 4px 0 0 0; color: #E2E8F0; font-size: 14.5px;\">State clearly why you are writing. For Editor: <i>&ldquo;Through the columns of your esteemed daily, I wish to draw the attention of the concerned authorities and the general public towards...&rdquo;</i>. For Complaint: <i>&ldquo;I am writing to express my extreme dissatisfaction regarding... purchased vide cash memo no... dated...&rdquo;</i>.</p>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 12px 14px; border-left: 4px solid #FFD54F; border-radius: 4px;\">\n        <b style=\"color: #FFD54F; font-size: 15.5px;\">Paragraph 2 &mdash; Detailed Elaboration (Causes, Impact &amp; Evidence):</b>\n        <p style=\"margin: 4px 0 0 0; color: #E2E8F0; font-size: 14.5px;\">Examine the core issue deeply. Discuss root causes, real-life consequences, suffering of affected citizens (students, elderly, patients), statistical dimensions, or specific technical flaws.</p>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.3); padding: 12px 14px; border-left: 4px solid #00E5FF; border-radius: 4px;\">\n        <b style=\"color: #00E5FF; font-size: 15.5px;\">Paragraph 3 &mdash; Action-Oriented Conclusion &amp; Constructive Remedies:</b>\n        <p style=\"margin: 4px 0 0 0; color: #E2E8F0; font-size: 14.5px;\">Provide 2 to 3 feasible, practical solutions. Conclude with a strong call-to-action: <i>&ldquo;It is strongly hoped that the municipal authorities will take swift remedial measures before a major catastrophe occurs.&rdquo;</i></p>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 2: THE FOUR CORE LETTER TYPES -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 35px;\">2. Comprehensive Taxonomy of Board Letter Types</h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 16px; margin: 18px 0;\">\n    <!-- LETTER TYPE 1 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(17, 153, 142, 0.4); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #11998E; margin: 0 0 8px 0; font-size: 17px;\">Type 1: Letters to the Editor</h3>\n      <p style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        Addressed to chief editors of prominent national or regional newspapers (e.g., <i>The Hindu</i>, <i>The Times of India</i>, <i>Greater Kashmir</i>). Deals with public grievances, rising social evils, climate crises, traffic hazards, or national policies.\n      </p>\n      <span style=\"color: #38EF7D; font-size: 13.5px; font-weight: bold;\">Key Trigger: &ldquo;Draw public &amp; governmental attention&rdquo;</span>\n    </div>\n\n    <!-- LETTER TYPE 2 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(17, 153, 142, 0.4); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #11998E; margin: 0 0 8px 0; font-size: 17px;\">Type 2: Business Letters (Enquiries &amp; Orders)</h3>\n      <p style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        Commercial transactions between clients and suppliers. Asking for product specifications, bulk discount quotes, payment terms, or confirming an order with an organized item table (Item No., Name, Brand, Quantity).\n      </p>\n      <span style=\"color: #38EF7D; font-size: 13.5px; font-weight: bold;\">Key Trigger: &ldquo;Quotation, delivery deadlines &amp; trade discounts&rdquo;</span>\n    </div>\n\n    <!-- LETTER TYPE 3 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(17, 153, 142, 0.4); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #11998E; margin: 0 0 8px 0; font-size: 17px;\">Type 3: Letters of Complaint</h3>\n      <p style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        Written to commercial firms about defective merchandise (refrigerators, TV sets, books, furniture) or to municipal officials regarding sewage blockages, garbage accumulation, or erratic water/electricity supply.\n      </p>\n      <span style=\"color: #38EF7D; font-size: 13.5px; font-weight: bold;\">Key Trigger: &ldquo;Cash memo reference, defect description &amp; demand for replacement&rdquo;</span>\n    </div>\n\n    <!-- LETTER TYPE 4 -->\n    <div style=\"background: rgba(15, 23, 42, 0.85); border: 1px solid rgba(17, 153, 142, 0.4); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #11998E; margin: 0 0 8px 0; font-size: 17px;\">Type 4: Official Letters to School Authorities</h3>\n      <p style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.6; margin: 0 0 10px 0;\">\n        Letters addressed to the Principal or Headmaster requesting leave of absence, character/transfer certificates, organizing intra-school competitions, or upgrading laboratory and library infrastructure.\n      </p>\n      <span style=\"color: #38EF7D; font-size: 13.5px; font-weight: bold;\">Key Trigger: &ldquo;Formal deference, student ID &amp; justified institutional appeal&rdquo;</span>\n    </div>\n  </div>\n\n  <!-- SECTION 3: COMPARATIVE MATRIX -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 35px;\">3. Master Comparative Checklist: Letter to Editor vs. Business vs. School</h2>\n  <div style=\"overflow-x: auto; margin: 18px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; background: rgba(0,0,0,0.35); font-size: 14.5px;\">\n      <thead>\n        <tr style=\"background: rgba(17, 153, 142, 0.2); color: #11998E;\">\n          <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 10px; text-align: left;\">Element</th>\n          <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 10px; text-align: left;\">Letter to the Editor</th>\n          <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 10px; text-align: left;\">Business Order / Enquiry</th>\n          <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 10px; text-align: left;\">Letter to Principal</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #38EF7D;\">Recipient Title</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">The Editor, [Name of Newspaper]</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">The Manager / Sales Head, [Firm]</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">The Principal, [School Name]</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #38EF7D;\">Standard Opening</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">&ldquo;Through the columns of your esteemed daily...&rdquo;</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">&ldquo;With reference to your quotation dated...&rdquo;</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">&ldquo;Most respectfully, I wish to state that...&rdquo;</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #38EF7D;\">Body Organization</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Cause, public suffering, remedies</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Tabular specifications, terms, discounts</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Reason for request, duration, student credentials</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #38EF7D;\">Closing Expectation</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Prompt administrative attention</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Timely dispatch, undamaged goods</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Favorable consideration &amp; approval</td>\n        </tr>\n        <tr>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px; font-weight: bold; color: #38EF7D;\">Complimentary Close</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Yours faithfully</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Yours faithfully / sincerely</td>\n          <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 9px;\">Yours obediently / sincerely</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- SECTION 4: EXAM PITFALLS & RED FLAGS -->\n  <div style=\"background: rgba(255, 82, 82, 0.08); border-left: 4px solid #FF5252; padding: 16px; border-radius: 6px; margin: 24px 0;\">\n    <h3 style=\"color: #FF5252; margin: 0 0 8px 0; font-size: 17px; font-weight: bold;\">⚠️ Critical Board Exam Pitfalls to Avoid:</h3>\n    <ul style=\"margin: 0; padding-left: 20px; color: #FFFFFF; font-size: 15px; line-height: 1.7;\">\n      <li><b>Never Write &ldquo;Your's&rdquo;:</b> Writing an apostrophe in <i>&ldquo;Yours faithfully&rdquo;</i> is one of the most common grammar penalties. &lsquo;Yours&rsquo; is already a possessive pronoun.</li>\n      <li><b>Avoid Punctuation Marks in Address Block:</b> Do not place commas at the end of each line of the address or after the salutation. The modern block format is completely open-punctuated.</li>\n      <li><b>Don&rsquo;t Command the Editor:</b> Saying <i>&ldquo;Please come and fix the broken streetlights in our colony&rdquo;</i> results in an instant 1-mark content deduction. The Editor only highlights issues for the authorities to act upon.</li>\n      <li><b>In Business Orders, Always Use a Tabular Grid:</b> Writing item specifications in a dense paragraph looks unprofessional and loses formatting credits. Always format orders as a neat table.</li>\n      <li><b>Word Limit Discipline (120&ndash;150 Words):</b> Going beyond 160 words wastes precious exam time and increases the risk of syntactic and spelling errors.</li>\n    </ul>\n  </div>\n\n</div>\n";

