export const c11EngW3HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <div style=\"background: rgba(17, 153, 142, 0.06); border: 1.5px solid #11998E; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #11998E; margin: 0 0 6px 0; font-size: 20px; font-weight: bold;\">📚 High-Scoring Board Exemplars &amp; Model Solutions</h2>\n    <p class=\"text-center\" style=\"color: #38EF7D; margin: 0; font-size: 14.5px;\">10 High-Yield Solved Board Letters &bull; Exact Word Limit &bull; Full Block Format</p>\n  </div>\n\n  <!-- PART A: LETTERS TO THE EDITOR -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 25px;\">Part A: Letters to the Editor Solved Exemplars</h2>\n\n  <!-- SAMPLE 1: RECKLESS DRIVING -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 1: Menace of Reckless Driving &amp; Underage Bikers</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Rohit/Ruchika, a resident of 14, Mall Road, Srinagar. You are deeply distressed by the increasing incidents of rash and negligent driving, stunt biking, and underage driving in your city, which have led to numerous fatal accidents. Write a letter in 120&ndash;150 words to the Editor of &lsquo;The Kashmir Times&rsquo;, highlighting the perils and suggesting effective measures to curb this menace.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        14, Mall Road<br/>\n        Srinagar<br/><br/>\n        18th October 2026<br/><br/>\n        The Editor<br/>\n        The Kashmir Times<br/>\n        Residency Road, Srinagar<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Growing menace of rash and underage driving in Srinagar</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Through the columns of your esteemed daily, I wish to express my profound concern over the alarming surge in rash, reckless, and underage driving on the major boulevards of our city.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        In recent months, roads such as the Boulevard and Bypass have transformed into perilous racetracks for teenagers performing dangerous stunts on high-powered motorbikes without helmets. Pedestrians, particularly school children and senior citizens, live under constant dread of being knocked down. The root causes lie in the sheer negligence of parents who entrust motor vehicles to unlicensed minors and the conspicuous absence of stringent traffic policing after sunset.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        To arrest this life-threatening trend, the traffic department must deploy speed-interceptors and CCTV surveillance at vulnerable intersections. Heavy monetary penalties and suspension of vehicle registrations must be enforced against parents of underage drivers. Additionally, mandatory road-safety seminars should be introduced across all secondary schools.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        I sincerely hope this appeal awakens both parents and the administration to act decisively before more innocent lives are tragically extinguished.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">ROHIT SHARMA</b><br/>\n        <span style=\"color: #38EF7D;\">Concerned Citizen</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 2: E-WASTE HAZARDS -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 2: Rising E-Waste &amp; Lack of Safe Disposal Mechanisms</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Alok/Anita, living at C-45, Green Park, New Delhi. With increasing digitalization, electronic waste (discarded phones, laptops, batteries) is accumulating rapidly and being dumped into municipal landfills, causing severe toxic contamination. Write a letter in 120&ndash;150 words to the Editor of &lsquo;The Indian Express&rsquo;, advocating for safe e-waste recycling hubs.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        C-45, Green Park<br/>\n        New Delhi<br/><br/>\n        12th September 2026<br/><br/>\n        The Editor<br/>\n        The Indian Express<br/>\n        Bahadur Shah Zafar Marg, New Delhi<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Urgent need for structured E-waste management and recycling hubs</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Through the columns of your widely read newspaper, I desire to draw the urgent attention of the Ministry of Environment and civic authorities to the catastrophic hazard posed by unscientific electronic waste disposal in the national capital.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        With the exponential proliferation of electronic gadgets, obsolete smartphones, computers, and lithium batteries are routinely discarded alongside domestic garbage. When unorganized scrap dealers dismantle these devices without protective gear, heavy neurotoxic metals such as lead, cadmium, and mercury leach directly into the soil and groundwater, triggering severe renal and neurological ailments among the populace.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        It is imperative that the government mandates &lsquo;Extended Producer Responsibility&rsquo; (EPR), compelling electronics manufacturers to establish convenient buy-back centers. Furthermore, residential welfare associations should be equipped with dedicated e-waste collection bins to ensure safe scientific recycling.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        Swift policy enforcement is vital to prevent our urban centers from degenerating into toxic electronic graveyards.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">ALOK VERMA</b><br/>\n        <span style=\"color: #38EF7D;\">Environmental Activist</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 3: MENTAL HEALTH COUNSELING IN SCHOOLS -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 3: Adolescent Mental Health &amp; Need for Trained School Counselors</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Meera/Manav, residing at 22, Sector 17, Chandigarh. You believe that excessive academic competition, peer pressure, and social media obsession are causing severe depression and anxiety among school adolescents. Write a letter to the Editor of &lsquo;The Tribune&rsquo; in 120&ndash;150 words urging the mandatory appointment of mental health counselors in all secondary schools.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        22, Sector 17<br/>\n        Chandigarh<br/><br/>\n        5th August 2026<br/><br/>\n        The Editor<br/>\n        The Tribune<br/>\n        Chandigarh<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Need for mandatory professional psychological counselors in schools</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Through the esteemed columns of your publication, I wish to focus public attention on the silent mental health crisis plaguing school-going adolescents in our society today.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Modern teenagers are trapped under a crushing vortex of cut-throat board exam percentiles, parental expectations, and algorithmic social media validation. Devoid of safe emotional outlets, hundreds of impressionable students suffer in isolation from acute clinical anxiety, sleep deprivation, and depression. Tragically, societal stigma surrounding psychological vulnerability prevents them from seeking timely parental intervention.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        To safeguard our youth, the Department of School Education must make the appointment of licensed child psychologists mandatory in all government and private institutions. Schools must conduct confidential wellness check-ups, mindfulness sessions, and peer-support circles.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        A nation&rsquo;s progress is meaningless if its young minds are broken under unseen psychological burdens. Early intervention can save countless precious lives.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">MEERA KAPOOR</b><br/>\n        <span style=\"color: #38EF7D;\">Youth Welfare Advocate</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- PART B: BUSINESS LETTERS (ENQUIRIES, ORDERS & COMPLAINTS) -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 35px;\">Part B: Business Letters Solved Exemplars</h2>\n\n  <!-- SAMPLE 4: PLACING AN ORDER -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 4: Placing a Bulk Order for School Sports Equipment</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Vikrant/Vineeta, Sports In-charge at Army Public School, Jammu. You wish to place a bulk order for various sports goods with M/s Pioneer Sports Emporium, Jalandhar. Write a formal business letter in 120&ndash;150 words specifying items, trade discounts, delivery terms, and payment mode.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        Army Public School<br/>\n        Cantonment Area, Jammu<br/><br/>\n        10th July 2026<br/><br/>\n        The Sales Manager<br/>\n        M/s Pioneer Sports Emporium<br/>\n        Railway Road, Jalandhar<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Supply of sports goods and athletic equipment for academic session 2026&ndash;27</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        We thank you for your quotation letter dated 2nd July 2026 and are pleased to place an order for the supply of following athletic equipment for our school sports complex:\n      </p>\n\n      <!-- ITEM TABLE -->\n      <div style=\"overflow-x: auto; margin: 12px 0;\">\n        <table style=\"width: 100%; border-collapse: collapse; background: rgba(0,0,0,0.4); font-size: 14px;\">\n          <thead>\n            <tr style=\"background: rgba(17, 153, 142, 0.25); color: #38EF7D;\">\n              <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 8px;\">S.No.</th>\n              <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 8px;\">Item Description</th>\n              <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 8px;\">Brand / Specifications</th>\n              <th style=\"border: 1px solid rgba(17, 153, 142, 0.4); padding: 8px;\">Quantity</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">1</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Cricket Bats (English Willow)</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">SS Master 5000 (Size 6 &amp; Full)</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">15 Pieces</td>\n            </tr>\n            <tr>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">2</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Football Match Balls</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Nivia Shining Star (Size 5)</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">20 Pieces</td>\n            </tr>\n            <tr>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">3</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Badminton Racquets</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Yonex Carbonex 8000</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">25 Pieces</td>\n            </tr>\n            <tr>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">4</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Basketballs</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px;\">Cosco Tournament Top Grain</td>\n              <td style=\"border: 1px solid rgba(255,255,255,0.1); padding: 7px; text-align: center;\">10 Pieces</td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        All items must be delivered in pristine condition at our school campus by 25th July 2026. As agreed in your quote, an institutional trade discount of 20% will be applied to the catalog price. Defective or substandard goods will be rejected at the supplier&rsquo;s expense. Payment will be released via RTGS within 7 days of inspection.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">VIKRANT CHOUDHARY</b><br/>\n        <span style=\"color: #38EF7D;\">Sports In-charge</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 5: LETTER OF COMPLAINT (DEFECTIVE AC) -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 5: Letter of Complaint &mdash; Defective Split Air Conditioner</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You purchased a 1.5-ton split air conditioner from M/s Modern Electronics, Connaught Place, New Delhi. Within three weeks of installation, the unit began making deafening vibrations and stopped cooling completely. Write a letter of complaint in 120&ndash;150 words demanding prompt technical repair or replacement under warranty.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        Flat No. 402, Sunrise Towers<br/>\n        Mayur Vihar Phase-I, Delhi<br/><br/>\n        24th May 2026<br/><br/>\n        The Customer Relations Manager<br/>\n        M/s Modern Electronics<br/>\n        B-Block, Connaught Place, New Delhi<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Complaint regarding defective Voltas 1.5 Ton Split AC (Invoice No. ME/2026/892)</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        I am writing to express my utter distress regarding the substandard performance of a Voltas 1.5-ton 5-star inverter split air conditioner purchased from your showroom on 2nd May 2026 vide Cash Memo No. ME/2026/892.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Barely three weeks after professional installation by your team, the compressor started producing an intolerable rattling noise, and the blower unit began discharging warm air. Despite registering two consecutive complaints on your customer portal (Ticket Nos. 78102 and 78440), no service engineer has visited our residence to date. With temperatures exceeding 44&deg;C, my elderly parents are enduring extreme physical agony.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        Since the appliance carries an unconditional 2-year comprehensive product warranty, I demand that you either depute a senior technician within 48 hours to rectify the fault or replace the defective unit entirely. Failing this, I shall be compelled to seek legal redressal at the District Consumer Disputes Redressal Commission.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">SANJEEV MALHOTRA</b><br/>\n        <span style=\"color: #38EF7D;\">Contact: 98110-45678</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- PART C: OFFICIAL LETTERS TO AUTHORITIES -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 35px;\">Part C: Official Letters to Civic &amp; School Authorities</h2>\n\n  <!-- SAMPLE 6: ERRATIC WATER SUPPLY TO MUNICIPAL COMMISSIONER -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 6: Letter to Municipal Commissioner on Contaminated Water Supply</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are the General Secretary of the RWA, Model Town, Ludhiana. For the past four weeks, your locality has been receiving erratic, muddy, and foul-smelling tap water, sparking fears of a cholera outbreak. Write an official letter in 120&ndash;150 words to the Municipal Commissioner seeking immediate intervention.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        Residents&rsquo; Welfare Association<br/>\n        Block-D, Model Town, Ludhiana<br/><br/>\n        14th June 2026<br/><br/>\n        The Municipal Commissioner<br/>\n        Municipal Corporation Headquarters<br/>\n        Civil Lines, Ludhiana<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Critical crisis of contaminated and irregular potable water supply in Model Town</b><br/><br/>\n        Sir\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        I wish to draw your immediate administrative attention to the severe potable water crisis afflicting over two thousand households in Model Town for the past month.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Water supply has dwindled to barely fifteen minutes a day, and the discharged water is heavily discolored, laden with silt, and emits a putrid stench. We suspect that an underground sewage pipeline has ruptured near the main pumping station, contaminating the municipal supply lines. Already, over two dozen residents, including vulnerable infants, have been hospitalized with acute gastroenteritis and jaundice.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        We urgently request you to dispatch a team of public health engineers to locate and repair the pipeline breach immediately. In the interim, kindly organize daily drinking water tankers to prevent a full-blown epidemic in our locality.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours faithfully<br/>\n        <b style=\"color: #FFFFFF;\">GURPREET SINGH</b><br/>\n        <span style=\"color: #38EF7D;\">General Secretary, RWA Model Town</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SAMPLE 7: PERMISSION FOR AI CLUB TO PRINCIPAL -->\n  <div style=\"margin: 22px 0;\">\n    <h3 style=\"color: #11998E; margin-bottom: 8px;\">Sample 7: Letter to School Principal for Founding an AI &amp; Robotics Club</h3>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin-bottom: 10px;\">\n      <b>Question:</b> You are Shreya/Shaurya of Class XI-Science, Delhi Public School, R.K. Puram. Write a formal letter to your School Principal requesting permission to inaugurate a student-led &lsquo;Artificial Intelligence and Robotics Club&rsquo; in the school, outlining its vision and required logistics.\n    </p>\n    <div style=\"background: #111B27; border: 1.5px solid #11998E; border-radius: 8px; padding: 18px; box-shadow: 0 4px 15px rgba(0,0,0,0.3); font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\">\n      <div style=\"color: #E2E8F0; font-size: 14.5px; line-height: 1.6; margin-bottom: 12px;\">\n        Class XI-A (Science Stream)<br/>\n        Delhi Public School, Sector XII, R.K. Puram<br/>\n        New Delhi<br/><br/>\n        16th November 2026<br/><br/>\n        The Principal<br/>\n        Delhi Public School<br/>\n        R.K. Puram, New Delhi<br/><br/>\n        <b style=\"color: #38EF7D;\">Subject: Request for permission to establish student-led AI &amp; Robotics Innovation Club</b><br/><br/>\n        Respected Madam\n      </div>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        Most respectfully, on behalf of the senior secondary science students, I write to seek your kind permission to inaugurate a student-driven &lsquo;Artificial Intelligence and Robotics Club&rsquo; in our institution for the ongoing academic term.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 12px;\">\n        With artificial intelligence reshaping scientific research, economics, and creative industries worldwide, theoretical textbook knowledge alone is insufficient. The proposed club will provide a collaborative platform for students of Classes IX to XII to master machine learning fundamentals, participate in national robotics olympiads, and build socially meaningful automation solutions. Mr. K.S. Rao, Senior PGT Computer Science, has generously consented to mentor the club as faculty patron.\n      </p>\n      <p style=\"color: #FFFFFF; font-size: 14.5px; line-height: 1.65; margin-bottom: 14px;\">\n        We request you to kindly grant us permission to utilize Computer Laboratory-3 for two hours every Friday after regular school hours. Your kind patronage will immensely foster a culture of technological innovation in our school.\n      </p>\n      <div style=\"font-size: 14px; color: #E2E8F0;\">\n        Yours obediently<br/>\n        <b style=\"color: #FFFFFF;\">SHREYA NARAYAN</b><br/>\n        <span style=\"color: #38EF7D;\">Class XI-A &bull; Roll No. 24</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- PART D: STEP-BY-STEP BOARD EXAM PRACTICE QUESTIONS -->\n  <h2 style=\"color: #11998E; font-weight: bold; border-bottom: 2px solid #11998E; padding-bottom: 6px; margin-top: 35px;\">Part D: Step-by-Step Board Exam Practice Questions</h2>\n\n  <div style=\"display: flex; flex-direction: column; gap: 18px; margin: 18px 0;\">\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #11998E; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #11998E; font-size: 15.5px;\">Practice Q1 (Letter to Editor &mdash; Stray Dog Menace):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You are Tanvi/Tarun of 32, Greater Kailash, Jammu. Increasing stray dog packs in residential sectors are biting school children and chasing two-wheelers at night. Write a letter in 120&ndash;150 words to the Editor of &lsquo;The Daily Excelsior&rsquo; urging municipal authorities to conduct animal birth control and anti-rabies vaccination drives.</p>\n      <span style=\"color: #38EF7D; font-size: 14px;\"><b>Examiner Key:</b> Must propose humane, legal solutions (sterilization, designated feeding zones) rather than violent culling.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #11998E; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #11998E; font-size: 15.5px;\">Practice Q2 (Business Enquiry &mdash; Book Exhibition):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You are the Librarian of Modern Public School, Chandigarh. You plan to organize a 3-day Book Fair on World Book Day. Write a letter in 120&ndash;150 words to M/s Oxford Book Distributors, Delhi, inquiring about discount slabs, consignment delivery, display racks, and return terms for unsold stock.</p>\n      <span style=\"color: #38EF7D; font-size: 14px;\"><b>Examiner Key:</b> Inquire about: Trade discounts (25-30%), freight charges, credit periods, and display setup assistance.</span>\n    </div>\n\n    <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #11998E; padding: 14px 16px; border-radius: 6px;\">\n      <b style=\"color: #11998E; font-size: 15.5px;\">Practice Q3 (Letter to Police &mdash; Frequent Thefts):</b>\n      <p style=\"margin: 6px 0; color: #FFFFFF;\">You are the President of the Colony Welfare Association, Sector 4, Rohini, Delhi. In the last three weeks, four house break-ins have occurred in broad daylight. Write an official letter in 120&ndash;150 words to the Station House Officer (SHO) demanding intensified night patrolling and a permanent police picket.</p>\n      <span style=\"color: #38EF7D; font-size: 14px;\"><b>Examiner Key:</b> State exact dates, lack of street patrolling, terror among residents, and demand CCTV surveillance checkposts.</span>\n    </div>\n  </div>\n\n</div>\n";

